import json, pathlib
ROOT = pathlib.Path(__file__).resolve().parent.parent
TR = {}

def register(ev, O, U):
    def t2(x):
        TR[x[1]] = x[2:5]
        return (x[0], x[1])
    def o(lab, fx, res): return O(t2(lab), ('', ''), fx, t2(res))
